 879	        const raw_contents: []const CAPI.ClipboardContent =
 880	            if (complete.contents) |v| v[0..complete.contents_len] else &.{};
 881	        const contents = conv_alloc.alloc(
 882	            terminal.clipboard.Content,
 883	            raw_contents.len,
 884	        ) catch |err| {
 885	            log.err("error completing clipboard request err={}", .{err});
 886	            alloc.destroy(state);
 887	            return;
 888	        };
 889	        defer conv_alloc.free(contents);
 890	        for (raw_contents, contents) |raw, *content| content.* = .{
 891	            .mime = std.mem.sliceTo(raw.mime, 0),
 892	            .data = raw.data[0..raw.len],
 893	        };
 894	
 895	        const raw_available: []const [*:0]const u8 =
 896	            if (complete.available) |v| v[0..complete.available_len] else &.{};
 897	        const available = conv_alloc.alloc(
 898	            []const u8,
 899	            raw_available.len,
 900	        ) catch |err| {
 901	            log.err("error completing clipboard request err={}", .{err});
 902	            alloc.destroy(state);
 903	            return;
 904	        };
 905	        defer conv_alloc.free(available);
 906	        for (raw_available, available) |raw, *mime| {
 907	            mime.* = std.mem.sliceTo(raw, 0);
 908	        }
